#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=6
REPO_ROOT=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/../.." && pwd -P)
cd -- "$REPO_ROOT"
ENV_FILE="$REPO_ROOT/.env"
grep -qxF '.env' .gitignore || { warn '.gitignore must exclude .env.'; exit 1; }
git check-ignore -q .env || { warn '.env is not ignored; refusing.'; exit 1; }
for tool in gh git cygpath clip.exe realpath; do
  command -v "$tool" >/dev/null || { warn "Missing required tool: $tool"; exit 1; }
done
SUBMISSION_REPO=Suhtetark-Kool/trusted-since-ai

banner "Saturday: private TrustED submission"

stage "Post TrustED questions (#33)"
if [[ -f docs/trusted-questions.md ]]; then
  clip.exe < docs/trusted-questions.md
else
  warn 'docs/trusted-questions.md is missing; prepare the questions manually.'
fi
open_url 'https://discord.com/app'
step 'Paste into the TrustED challenge channel on the Since AI server.'
pause 'Press Enter after posting (or to continue while awaiting an answer).'
say 'These answers are public. Leave blank if unanswered; re-run later.'
ask ORGANISER_GITHUB_HANDLES 'Organiser GitHub handles (comma-separated, no @):'
ask ROWMAP_DELIVERY 'Agreed row-map delivery instructions (public text):'
write_env ORGANISER_GITHUB_HANDLES "$ORGANISER_GITHUB_HANDLES"
write_env ROWMAP_DELIVERY "$ROWMAP_DELIVERY"

stage "Defender exclusion (manual, administrator)"
warn 'This excludes the entire AI directory from Defender scanning; use only if intended.'
say "Run in an ADMIN PowerShell: Add-MpPreference -ExclusionPath 'C:\Users\kivas\AI'"
say "Undo: Remove-MpPreference -ExclusionPath 'C:\Users\kivas\AI'"
pause 'Press Enter when done, or if you choose not to add the exclusion.'

stage "Create the private organiser repository (#34)"
if gh repo view "$SUBMISSION_REPO" >/dev/null 2>&1; then
  say 'Suhtetark-Kool/trusted-since-ai already exists; creation skipped.'
elif confirm 'Create Suhtetark-Kool/trusted-since-ai as a PRIVATE repository?'; then
  if ! gh repo create "$SUBMISSION_REPO" --private --description 'pets_submission for TrustED organiser checks (private; contains row maps)'; then
    warn 'Creation failed (possibly organisation permissions). Ask SuhtetarkKool to:'
    step 'Open GitHub and create trusted-since-ai PRIVATE in the Suhtetark-Kool organisation.'
    step 'Add Kivaste as an administrator of that repository.'
    pause 'Press Enter after SuhtetarkKool has created it, or Ctrl-C to resume later.'
  fi
else
  warn 'No repository created. Re-run after it exists.'
fi
write_env SUBMISSION_REPO "$SUBMISSION_REPO"
# Existence alone is not proof that row maps can safely be uploaded.
visibility=$(gh repo view "$SUBMISSION_REPO" --json visibility --jq .visibility) || exit 1
[[ "$visibility" == PRIVATE ]] || { warn 'Submission repository is not verified PRIVATE; refusing.'; exit 1; }

stage "Invite organisers read-only"
invited=()
if [[ -z "${ORGANISER_GITHUB_HANDLES//[[:space:]]/}" ]]; then
  say 'No organiser handles yet: re-run after TrustED answers.'
else
  IFS=',' read -r -a handles <<< "$ORGANISER_GITHUB_HANDLES"
  for handle in "${handles[@]}"; do
    handle="${handle//[[:space:]]/}"
    [[ "$handle" =~ ^[A-Za-z0-9][A-Za-z0-9-]{0,38}$ ]] || { warn 'Invalid GitHub handle; correct ORGANISER_GITHUB_HANDLES and re-run.'; exit 1; }
    if confirm "Invite $handle with read-only (pull) permission?"; then
      if gh api -X PUT "repos/$SUBMISSION_REPO/collaborators/$handle" -f permission=pull >/dev/null; then
        invited+=("$handle")
      else
        warn "Invitation failed for $handle; check organisation permissions and re-run."
        SKIPPED+=("Read-only invitation for $handle")
      fi
    else
      SKIPPED+=("Read-only invitation for $handle")
    fi
  done
fi

stage "Verify and push pets_submission (after #30 lands)"
say 'Build the submission with ticket #30 first. Only file presence and counts are checked here.'
ask PETS_SUBMISSION_DIR 'pets_submission directory [default C:\Users\kivas\AI\sinceai-out\pets_submission]:'
PETS_SUBMISSION_DIR=${PETS_SUBMISSION_DIR:-'C:\Users\kivas\AI\sinceai-out\pets_submission'}
write_env PETS_SUBMISSION_DIR "$PETS_SUBMISSION_DIR"
bundle=$(realpath -e -- "$(cygpath -u "$PETS_SUBMISSION_DIR")") || exit 1
[[ -d "$bundle" ]] || { warn 'Submission directory does not exist.'; exit 1; }
public=$(realpath -e -- "$REPO_ROOT")
# Windows paths are case-insensitive; realpath resolves symlinks before comparison.
case "${bundle,,}/" in
  "${public,,}/"*) warn 'Refusing a submission directory inside the public repository.'; exit 1 ;;
esac
case "${public,,}/" in
  "${bundle,,}/"*) warn 'Refusing a submission directory containing the public repository.'; exit 1 ;;
esac
[[ -f "$bundle/unseen_field_labels.csv" ]] || { warn 'Missing unseen labels file.'; exit 1; }
[[ -f "$bundle/customer_service_eval_redacted.csv" || -f "$bundle/customer_service_eval_spans.jsonl" ]] || {
  warn 'Missing customer-service eval redaction output.'; exit 1;
}
[[ -z "$(find "$bundle" -path "$bundle/.git" -prune -o -type l -print -quit)" ]] || {
  warn 'Submission contains symlinks; refusing.'; exit 1;
}
dataset_count=0
shopt -s nullglob
for dataset in "$bundle"/*/; do
  [[ "${dataset%/}" == "$bundle/.git" ]] && continue
  table_count=0
  map_count=0
  file_count=0
  for file in "$dataset"*; do
    [[ -f "$file" ]] || continue
    file_count=$((file_count + 1))
    base=${file##*/}
    case "$base" in
      rowmap_*.csv) map_count=$((map_count + 1)) ;;
      *.csv)
        table_count=$((table_count + 1))
        [[ -f "${dataset}rowmap_$base" ]] || { warn 'A protected table is missing its row map.'; exit 1; }
        ;;
    esac
  done
  printf '  Dataset subfolder %s: %s files, %s protected tables, %s row maps\n' "$(basename "$dataset")" "$file_count" "$table_count" "$map_count"
  if (( table_count > 0 )); then dataset_count=$((dataset_count + 1)); fi
done
(( dataset_count > 0 )) || { warn 'No dataset subfolder with protected tables and row maps.'; exit 1; }
say 'These counts do NOT replace packager validation or the pets-eval scorecards.'
forbidden_count=$(find "$bundle" -path "$bundle/.git" -prune -o \( -iname '.env' -o -iname '.env.*' -o -iname '*.key' -o -iname 'truth' -o -iname 'Briefs' \) -print | wc -l)
(( forbidden_count == 0 )) || { warn "Submission contains $forbidden_count forbidden secret/kit/truth paths; refusing."; exit 1; }
uploaded=0
if confirm 'Push this bundle? This sends row maps to a private repo shared with organisers'; then
  visibility=$(gh repo view "$SUBMISSION_REPO" --json visibility --jq .visibility) || exit 1
  [[ "$visibility" == PRIVATE ]] || { warn 'Repository is not PRIVATE; refusing upload.'; exit 1; }
  (
    cd -- "$bundle"
    # Never accidentally stage the parent checkout or use an external gitdir.
    [[ ! -f .git && ! -L .git ]] || { warn 'Linked/external gitdir is not allowed.'; exit 1; }
    if [[ ! -d .git ]]; then git init --quiet; fi
    top=$(realpath -e -- "$(cygpath -u "$(git rev-parse --show-toplevel)")")
    [[ "${top,,}" == "${bundle,,}" ]] || { warn 'Git root is not the bundle directory.'; exit 1; }
    remote='https://github.com/Suhtetark-Kool/trusted-since-ai.git'
    if git remote get-url origin >/dev/null 2>&1; then
      [[ "$(git remote get-url origin)" == "$remote" ]] || { warn 'Unexpected origin URL; refusing.'; exit 1; }
      [[ "$(git remote get-url --push origin)" == "$remote" ]] || { warn 'Unexpected push URL; refusing.'; exit 1; }
    else
      git remote add origin "$remote"
    fi
    git -c core.autocrlf=false add --all
    if ! git diff --cached --quiet; then git -c core.hooksPath=/dev/null commit --quiet -m 'Update private pets_submission'; fi
    git branch -M main
    git -c core.hooksPath=/dev/null push origin main
  )
  uploaded=1
else
  SKIPPED+=('Private submission upload')
fi

stage "Ask TrustED to run organiser checks"
if (( ! uploaded )); then
  message='Our private pets_submission upload is still pending. We will follow up with the private repository and organiser invitations once it is ready.'
elif (( ${#invited[@]} )); then
  invited_text=$(IFS=','; printf '%s' "${invited[*]}")
  message="Our pets_submission is in the private repo Suhtetark-Kool/trusted-since-ai; we've invited $invited_text read-only. Could you run the hidden-attacker, unseen-label and eval-redaction checks? Thanks!"
else
  message='Our pets_submission is in the private repo Suhtetark-Kool/trusted-since-ai; organiser invitations are still pending. Could you confirm the handles and run the hidden-attacker, unseen-label and eval-redaction checks once access is ready? Thanks!'
fi
printf '%s' "$message" | clip.exe
open_url 'https://discord.com/app'
step 'Review the message before pasting into the TrustED challenge channel on the Since AI server.'
warn 'Do not claim the upload is complete unless stage 5 actually pushed it.'
pause 'Press Enter after posting, or to leave the message on the clipboard.'

finish
}

run_wizard "$@"; exit
